@AbapCatalog.sqlViewName: 'ZVMATCRM'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Material Master Data for CRM Integration'
@Metadata.ignorePropagatedAnnotations: true
@OData.publish: true
define view Z_C_MaterialCRM
  as select from    mara
    left outer join makt           on  makt.matnr = mara.matnr
                                   and makt.spras = $session.system_language
    left outer join marm           on marm.matnr = mara.matnr
    inner join      mvke           on  mvke.matnr = mara.matnr
                                 //  and mvke.vkorg = '3000'
                                   //and mvke.vtweg = '02'
    inner join      tvm1t as tvm1t on  tvm1t.mvgr1 = mvke.mvgr1
                                   and tvm1t.spras = $session.system_language
{
      @EndUserText.label: 'Material Number'
  key mara.matnr  as Material,
      @EndUserText.label: 'Material Type'
      mara.mtart  as MaterialType,
      @EndUserText.label: 'Material Group'
      mara.matkl  as MaterialGroup,
      @EndUserText.label: 'Base Unit of Measure'
      mara.meins  as BaseUnit,
      @EndUserText.label: 'Material Description'
      makt.maktx  as MaterialDescription,
      @EndUserText.label: 'Alternative Unit of Measure'
      marm.meinh  as AlternativeUnit,
      @EndUserText.label: 'Numerator for Conversion to Base Units of Measure'
      marm.umrez  as Numerator,
      @EndUserText.label: 'Sales Organization'
      mvke.vkorg  as SalesOrganization,
      @EndUserText.label: 'Distribution Channel'
      mvke.vtweg  as DistributionChannel,
      @EndUserText.label: 'Sales Unit'
      mvke.vrkme  as SalesUnit,
      @EndUserText.label: 'Material Group 1'
      mvke.mvgr1  as MaterialGroup1,
      @EndUserText.label: 'Material Group Description'
      tvm1t.bezei as MaterialGroup1Desc
}
