@AbapCatalog.sqlViewName: 'ZIVNDPOSCR'
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PO Vendor Score'

@VDM.viewType: #COMPOSITE
@Analytics.dataCategory: #CUBE

define view Z_I_PO_VENDOR_SCORE
as select from Z_I_PO_VENDOR_AGG as agg

left outer join zvendor_score as z
  on z.ebeln = agg.ebeln

{

  /* ===================== */
  /* KEYS */
  /* ===================== */

  key agg.ebeln,
  agg.lifnr,
  agg.name1,
  agg.name2,
 agg.companycode,
 agg.PurchaseOrg,
 agg.plant,

  /* ===================== */
  /* BASE DATA */
  /* ===================== */

  agg.total_supplied_qty,
  agg.total_otd_qty,
  agg.total_delay_days,

  /* ===================== */
  /* MANUAL SCORES */
  /* ===================== */

  coalesce( cast( z.qualityscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) as quality_score,

  coalesce( cast( z.responsscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) as responsiveness_score,

  coalesce( cast( z.documentscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) as document_score,

  /* ===================== */
  /* DELIVERY METRICS */
  /* ===================== */

  case
    when agg.total_supplied_qty = 0 then 0
    else division( agg.total_otd_qty * 100, agg.total_supplied_qty, 2 )
  end as delivery_percent,

  case
    when agg.total_supplied_qty = 0 then 0
    else division( agg.total_delay_days, agg.total_supplied_qty, 2 )
  end as avg_delay,

  case
    when agg.total_supplied_qty = 0 then 0
    else
      division( agg.total_otd_qty * 100, agg.total_supplied_qty, 2 )
      -
      division( agg.total_delay_days, agg.total_supplied_qty, 2 )
  end as delivery_score,

  /* ===================== */
  /* WEIGHTED COMPONENTS */
  /* ===================== */

  case
    when agg.total_supplied_qty = 0 then 0
    else
      division(
        (
          division( agg.total_otd_qty * 100, agg.total_supplied_qty, 2 )
          -
          division( agg.total_delay_days, agg.total_supplied_qty, 2 )
        ) * 30,
        100,
        2
      )
  end as weighted_delivery,

  division(
    coalesce( cast( z.qualityscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 30,
    100,
    2
  ) as weighted_quality,

  division(
    coalesce( cast( z.responsscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 20,
    100,
    2
  ) as weighted_responsiveness,

  division(
    coalesce( cast( z.documentscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 20,
    100,
    2
  ) as weighted_document,

  /* ===================== */
  /* FINAL SCORE */
  /* ===================== */

  case

    when agg.total_supplied_qty = 0 then

         division(
           coalesce( cast( z.qualityscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 30,
           100,
           2
         )
       + division(
           coalesce( cast( z.responsscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 20,
           100,
           2
         )
       + division(
           coalesce( cast( z.documentscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 20,
           100,
           2
         )

    else

         division(
           (
             division( agg.total_otd_qty * 100, agg.total_supplied_qty, 2 )
             -
             division( agg.total_delay_days, agg.total_supplied_qty, 2 )
           ) * 30,
           100,
           2
         )

       + division(
           coalesce( cast( z.qualityscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 30,
           100,
           2
         )

       + division(
           coalesce( cast( z.responsscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 20,
           100,
           2
         )

       + division(
           coalesce( cast( z.documentscore as abap.dec(5,2) ), cast( 100 as abap.dec(5,2) ) ) * 20,
           100,
           2
         )

  end as po_score

}
