@AbapCatalog.sqlViewName: 'ZIVNDBASE'
@AbapCatalog.compiler.compareFilter: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Vendor Performance - Base Data'
 
define view Z_I_VENDOR_BASE
as select from ekko
 
inner join ekpo
  on ekpo.ebeln = ekko.ebeln
 
/* Vendor master */
inner join lfa1
  on lfa1.lifnr = ekko.lifnr
 
/* Vendor company code data */
left outer join lfb1
  on lfb1.lifnr = ekko.lifnr
and lfb1.bukrs = ekko.bukrs
 
/* Vendor purchase org data */
left outer join lfm1
  on lfm1.lifnr = ekko.lifnr
and lfm1.ekorg = ekko.ekorg
 
/* Purchasing group text */
left outer join t024
  on t024.ekgrp = ekko.ekgrp
 
/* PO schedule line */
left outer join eket
  on eket.ebeln = ekpo.ebeln
and eket.ebelp = ekpo.ebelp
and eket.etenr = '0001'
 
/* GR History (NO BWART FILTER) */
left outer join ekbe
  on ekbe.ebeln = ekpo.ebeln
and ekbe.ebelp = ekpo.ebelp
 
{
  /* ===== Keys ===== */
  key ekko.ebeln,
  key ekpo.ebelp,
 
  /* ===== Vendor ===== */
  ekko.lifnr,
  lfa1.name1,
  lfa1.name2,
 
  /* ===== Org ===== */
  ekko.bukrs as companycode,
  ekko.ekorg as PurchaseOrg,
  ekpo.werks as plant,
 
  /* ===== Purchasing ===== */
  ekko.ekgrp,
  t024.eknam,
 
  /* ===== Item ===== */
  ekpo.txz01 as item_description,
 
  /* ===== Qty ===== */
  ekpo.menge as order_qty,
  ekpo.meins as order_unit,
 
  /* ===== Price ===== */
  ekpo.netpr as net_order_price,
 
  /* ===== WBS ===== */
  ekpo.ps_psp_pnr as wbs_element,
 
  /* ===== Dates ===== */
  eket.eindt as po_delivery_date,
  ekko.bedat as po_date,
 
  /* ===== GR ===== */
  ekbe.budat as gr_date,
 
  case
    when ekbe.shkzg = 'S' then ekbe.menge
    when ekbe.shkzg = 'H' then - ekbe.menge
    else 0
  end as gr_qty,
 
  /* ===== Vendor Flags ===== */
  lfb1.zahls,
  lfb1.sperr,
  lfm1.sperm
 
}
/*+[internal] {
