@AbapCatalog.sqlViewName: 'ZIVNDITEM'
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Vendor Item KPI'
 
@VDM.viewType: #COMPOSITE
 
define view Z_I_VENDOR_ITEM
as select from Z_I_VENDOR_BASE
{
 
  key ebeln,
  key ebelp,
 
  lifnr,
  name1,
  name2,
  
 
  order_qty,
  po_delivery_date,
  gr_date,
 companycode,
 PurchaseOrg,
 plant,
  /* ===================== */
  /* SUPPLIED QTY */
  /* ===================== */
 
  coalesce( gr_qty, 0 ) as supplied_qty,
 
  /* ===================== */
  /* OTD QTY */
  /* ===================== */
 
  case
    when gr_date <= po_delivery_date
    then coalesce( gr_qty, 0 )
    else 0
  end as otd_qty,
 
  /* ===================== */
  /* DELAY DAYS */
  /* ===================== */
 
  case
    when gr_date > po_delivery_date
    then dats_days_between( po_delivery_date, gr_date )
    else 0
  end as delay_days
 
}
