//@AbapCatalog.compiler.compareFilter: true
@AccessControl.authorizationCheck: #CHECK
@EndUserText.label: 'UC1 - Route Card: PP Orders + Routing + WC + Confirmations'
@VDM.viewType: #CONSUMPTION

define view entity ZAI_UC1_ROUTE_CARD_INPUT
  as select from aufk  as OrderHdr
  inner join    afko   as PPHdr    on  PPHdr.aufnr   = OrderHdr.aufnr
  inner join    afpo   as PPItem   on  PPItem.aufnr  = OrderHdr.aufnr
                                   and PPItem.posnr  = '0001'
  inner join    afvc   as Ops      on  Ops.aufpl     = PPHdr.aufpl
  inner join    crhd   as WC       on  WC.objid      = Ops.arbid
                                  // and WC.mandt      = $session.client
  left outer join makt as MatTxt   on  MatTxt.matnr  = PPItem.matnr
                                   and MatTxt.spras  = $session.system_language
  left outer join afru as Confs    on  Confs.aufnr   = OrderHdr.aufnr
                                   and Confs.vornr   = Ops.vornr
{
  key OrderHdr.aufnr                as ProductionOrderNo,
      PPItem.matnr                  as MaterialNo,
      MatTxt.maktx                  as MaterialDescription,
      OrderHdr.werks                as Plant,
     // PPItem.psmng                  as OrderQuantity,
      PPItem.meins                  as UnitOfMeasure,
      OrderHdr.auart                as OrderType,
      PPHdr.gstrs                   as BasicStartDate,
      PPHdr.gltrs                   as BasicFinishDate,
      case OrderHdr.auart
        when 'PP01' then 'HIGH'
        when 'PP02' then 'MEDIUM'
        else             'LOW'
      end                           as Priority,
     // OrderHdr.verak                as MRPController,
      //OrderHdr.sttxt                as OrderStatus,
   cast( Ops.vornr as abap.char(4) )  as OperationNo,
      WC.arbpl                      as WorkCenterID,
     // WC.ktext                      as WorkCenterDescription,
      Ops.ltxa1                     as OperationDescription,
     // cast( Ops.ruste as abap.dec(13,3) ) as SetupTimeMin,
     // cast( Ops.beaze as abap.dec(13,3) ) as MachineTimeMin,
     // Ops.menge                     as PlannedQuantity,
      Ops.steus                     as ControlKey,
      Ops.aplzl                     as RoutingSequence,
     // Confs.lmnga                   as ActualQtyConfirmed,
    //  Confs.xmnga                   as ScrapQuantity,
      Confs.isdd                    as ConfirmationDate,
      case when Confs.lmnga is not null then 'CONF_FINAL' else 'PENDING' end
                                    as SignalType
}
where OrderHdr.autyp = '10'
