@AbapCatalog.sqlViewName: 'ZBOM_EXP'
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PP BOM Report'
@OData.publish: true 
@VDM.viewType: #CONSUMPTION 
@Analytics.dataCategory: #CUBE
@Analytics.query: false 

define view  ZBOM_EXPLODE 
   // with parameters 
   // @Consumption.valueHelpDefinition: [{ 
    //    entity : { name: 'I_Material' , element: 'Material'}
   //  }]
     
   //  p_matnr_low : matnr , 
  //   p_matnr_high : matnr 
     
as select from
    I_MaterialBOMLink            as          bomlink
inner join I_BOMComponentWithKeyDate( P_KeyDate: $session.system_date )  as bomcomp
on bomcomp.BillOfMaterial        = bomlink.BillOfMaterial
and bomcomp.BillOfMaterialVariant = bomlink.BillOfMaterialVariant
and bomcomp.BillOfMaterialCategory = bomlink.BillOfMaterialCategory
inner join afko                  as        bomafko
on bomafko.plnbez = bomlink.Material
and bomlink.BillOfMaterialVariant = bomcomp.BillOfMaterialVariant
left outer join  mseg            as          mseg
on mseg.aufnr = bomafko.aufnr  
and mseg.matnr = bomcomp.BillOfMaterialComponent
and ( mseg.bwart = '261' or mseg.bwart = '262' )
left outer join aufk             as         aufk 
on aufk.aufnr = bomafko.aufnr
 left outer join jest             as          jest
 on jest.objnr = aufk.objnr and jest.inact = ''
 inner join tj02t            as          tj02t on tj02t.istat = jest.stat and tj02t.spras = 'E' 

{

  key  bomlink.BillOfMaterial , 
  key  bomlink.Material , 
  key  bomafko.aufnr ,
       bomlink.Plant ,
       bomcomp.BillOfMaterialComponent , 
       bomcomp.ComponentDescription ,  
     
    @Semantics.quantity.unitOfMeasure:  'BillOfMaterialItemUnit' 
    @DefaultAggregation: #SUM 
    bomcomp.BillOfMaterialItemQuantity  ,
    
     @Semantics.quantity.unitOfMeasure:  'BillOfMaterialItemUnit' 
     @DefaultAggregation: #SUM   
     mseg.erfmg ,
     bomcomp.BillOfMaterialItemUnit  ,
     
     case 
     when tj02t.istat = 'I0001' then 'Created'
     when tj02t.istat = 'I0002' then 'Released'
     when tj02t.istat = 'I0009' then 'Confirmed'
     when tj02t.istat = 'I0010' then 'Partially Conf'
     when tj02t.istat = 'I0012' then 'Delivered'
     else 'Other'
    end as status
     
}

group by 

  bomlink.BillOfMaterial,
  bomlink.Material,
  bomafko.aufnr,
  bomlink.Plant,
  bomcomp.BillOfMaterialComponent,
  bomcomp.ComponentDescription,
  bomcomp.BillOfMaterialItemUnit,
  bomcomp.BillOfMaterialItemQuantity , 
  mseg.erfmg ,
  tj02t.istat
    

 // where bomlink.Material between $parameters.p_matnr_low and $parameters.p_matnr_high

/*+[internal] {
