@AbapCatalog.sqlViewName: 'ZDEMO_VBAK'
@EndUserText.label: 'Arithmetic + String + Date Demo on VBAK'
define view ZC_DEMO_VBAK
  as select from vbak as V
{
    key V.vbeln,          // Sales Order
 
    V.netwr,              // Net Value
    V.waerk,              // Currency
    V.erdat,              // Creation Date
    V.kunnr,              // Customer
 
    /* =========================
       Arithmetic Operations
       ========================= */
 
    /* Addition */
    ( V.netwr + 100 ) as NetPlus100,
 
    /* Subtraction */
    ( V.netwr - 50 ) as NetMinus50,
 
    /* Multiplication */
    ( V.netwr * 2 ) as NetDouble,
 
   cast( V.netwr as abap.fltp ) / 10.0 as NetDiv10,
 

 
    /* =========================
       CONCAT (String)
       ========================= */
 
    concat( V.vbeln, V.kunnr ) as OrderCustomer,
 
    concat(
       concat('Order: ', V.vbeln),
       concat(' Customer: ', V.kunnr)
    ) as FullText,
 
    /* Better way */
    concat_with_space( V.vbeln, V.kunnr, 1 ) as Order_Customer_Space,
 
    /* =========================
       Date Function
       ========================= */
 
    dats_days_between(
       V.erdat,
        cast( $session.system_date as abap.dats )
    ) as OrderAgeDays
}
