@Analytics.dataCategory: #CUBE
@EndUserText.label: 'Location Wise Sales Report'

define view entity ZC_LocationWiseSales

  as select from    ZC_LocationSalesReport as sales

    left outer join ZC_BudgetSummary       as budget on  sales.werks = budget.werks
                                                     and sales.spart = budget.division
                                                     and sales.bzirk = budget.hq

{

  key sales.werks,

//  key sales.vkbur,

  key sales.spart,

      sales.bezei,

      sales.vtext,


      /* Gross Sales in Lakhs */
      cast(
          sales.GrossSales / 100000
          as abap.dec(23,2)
      ) as GrossSalesLacs,


      /* Net Sales Calculation */
      cast(
          (
            sales.GrossSales
            - sales.ReturnSales
            - sales.Damage
            - sales.Expiry
            - sales.PriceDiff
            - sales.Secondary
            - sales.EPD
          ) / 100000
          as abap.dec(23,2)
      ) as NetSalesLacs,


      /* Target in Lakhs */
      cast(
          budget.Target / 100000
          as abap.dec(23,2)
      ) as TargetLacs,


      /* Variance in Lakhs */
      cast(
          (
            (
              sales.GrossSales
              - sales.ReturnSales
              - sales.Damage
              - sales.Expiry
              - sales.PriceDiff
              - sales.Secondary
              - sales.EPD
            )
            -
            budget.Target
          ) / 100000
          as abap.dec(23,2)
      ) as VarianceLacs,


      /* Achievement Percentage */
      cast(
          case
              when budget.Target > 0
              then
                (
                  (
                    sales.GrossSales
                    - sales.ReturnSales
                    - sales.Damage
                    - sales.Expiry
                    - sales.PriceDiff
                    - sales.Secondary
                    - sales.EPD
                  )
                  /
                  budget.Target
                ) * 100

              else 0
          end
          as abap.dec(5,2)
      ) as AchievementPercent

}
