define view entity ZC_PurchaseRegisterGL
  as select from ZI_PurchRegDoc as Doc
//
    inner join   ZI_PurchRegDetail       as Det   on  Det.Bukrs = Doc.Bukrs
                                                   and Det.Belnr = Doc.Belnr
                                                   and Det.Gjahr = Doc.Gjahr
                                                   and Det.Shkzg = Doc.DerivedShkzg
//
    left outer join ZI_PurchRegGrossSum  as Grs   on  Grs.Bukrs = Doc.Bukrs
                                                   and Grs.Belnr = Doc.Belnr
                                                   and Grs.Gjahr = Doc.Gjahr
//
    left outer join ZI_PurchRegTaxAmounts as Tax  on  Tax.Bukrs = Det.Bukrs
                                                  and Tax.Belnr = Det.Belnr
                                                   and Tax.Gjahr = Det.Gjahr
                                                   and Tax.Txgrp = Det.Txgrp
                                                   and Tax.Shkzg = Doc.DerivedShkzg

    left outer join bseg  as TaxLineDyn         on  TaxLineDyn.bukrs = Det.Bukrs
                                                  and TaxLineDyn.belnr = Det.Belnr
                                                  and TaxLineDyn.gjahr = Det.Gjahr
                                                  and TaxLineDyn.buzid = 'T'
                                                 and TaxLineDyn.shkzg = Doc.DerivedShkzg
//
    left outer join bseg  as TaxLineH           on  TaxLineH.bukrs = Det.Bukrs
                                                  and TaxLineH.belnr = Det.Belnr
                                                 and TaxLineH.gjahr = Det.Gjahr
                                                  and TaxLineH.buzid = 'T'
                                                 and TaxLineH.shkzg = 'H'
//
   left outer join marc  as Marc               on  Marc.matnr = Det.Matnr
                                                  and Marc.werks = Det.Werks
//
    left outer join ZI_PurchRegVendorLine as Vln on  Vln.Bukrs = Det.Bukrs
                                                  and Vln.Belnr = Det.Belnr
                                                  and Vln.Gjahr = Det.Gjahr
//
   left outer join lfa1  as Vendor              on  Vendor.lifnr = Vln.Lifnr

    left outer join t005u as Region              on  Region.land1 = Doc.CompanyLand1
                                                  and Region.bland = Vendor.regio
                                                  and Region.spras = 'E'
{
      key Doc.Bukrs                                                    as Company_Code,
      key Doc.Belnr                                                    as Document_No,
      key Doc.Gjahr                                                    as Fiscal_Year,
//      key Det.Buzei                                                    as Buzei,
