          Doc.Blart                                                    as Document_Type,
          Det.Kostl                                                    as Cost_Center,
          Det.Prctr                                                    as Profit_Center,
          Det.Text1Tax                                                 as Tax_Currency,
          coalesce( Tax.VatRate, 0 )                                    as Vat_Rate,
           coalesce( TaxLineH.ktosl, TaxLineDyn.ktosl )                  as VatCode,
          Doc.Bldat                                                    as Document_Date,
          Doc.Budat                                                    as Posting_Date,
          Doc.Waers                                                    as Currency,
          Doc.Kursf                                                    as Exchange_Rate,
          Doc.Xblnr                                                    as Invoice_No,
          Vln.Lifnr                                                    as Vendor,
          Vendor.name1                                                 as Name,
          Vendor.ort01                                                 as City,
           Region.bezei                                                 as Region,
          Det.Gsber                                                    as Bussiness_Area

//          // sign-flipped amounts (mirrors the last ABAP loop's *-1 logic)
////          Det.Wrbtr        * Doc.SignMultiplier                        as Wrbtr,
//          Det.Dmbtr         * Doc.SignMultiplier                        as Dmbtr,
////          coalesce( Tax.BsetTaxableVal, Det.TaxableVal )
