@AbapCatalog.sqlViewName: 'ZCDS_PURCHITEM'
@AbapCatalog.compiler.compareFilter: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'CDS View for Purchase item'
@Metadata.ignorePropagatedAnnotations: true
@ObjectModel.usageType.dataClass: #TRANSACTIONAL
@ObjectModel.usageType.serviceQuality: #X
@ObjectModel.usageType.sizeCategory: #S
@OData.publish: true
define view ZCDS_PURCHASEITEM 
//with parameters p_ebeln : ebeln,
//                p_ebelp : ebelp
 as select from ekpo as _ekpo association[0..*] to ekbe as _ekbe 
   on _ekpo.ebeln = _ekbe.ebeln and
      _ekpo.ebelp = _ekbe.ebelp
   association[0..1] to mara as _mara on _ekpo.matnr = _mara.matnr
{
    key _ekpo.ebeln as PurchaseOrder,
    key _ekpo.ebelp as LineItem,
        _ekpo.werks as Plant,
        case _ekpo.werks
         when 'MBI1' then 'P-MBI1'
         when 'SM02' then 'P-SM02'
         else _ekpo.werks
         end as PlantSpecification,
        //_ekpo.matnr as Material,     
        _ekpo.menge as Quantity,
        _ekpo.meins as Unit,
        _ekpo.netpr as NetPrice,
        _ekpo.netwr as NetValue,
        _ekpo.inco1 as IncoTerms,
        case _ekpo.inco1 
          when '' then 'NULL'
          else _ekpo.inco1
        end as IncoTerms_New , 
        _mara.matnr as Material,
        _mara.mtart as MaterialType,
        _mara.matkl as MaterialGroup,
        _ekbe.dmbtr as AmountInLC,
        _ekbe.wrbtr as Amount,
        _ekbe.waers as Currency,
        _ekbe.xblnr as ReferenceDoc,
        _ekbe.mwskz as TaxCode,
        $session.user as UserName,
        $session.client as Client,
        $session.system_date as SystemDate
        
        
}
