define view entity zDPR_REPORT
  with parameters
    p_plant : werks_d,
    p_date  : budat,
    // p_shift : kaptprog,
    // p_work : arbpl,
    p_order : aufnr
  // p_material : matnr
  as select from    afru
    inner join      aufk on afru.aufnr = aufk.aufnr

    inner join      afpo on afru.aufnr = afpo.aufnr

    left outer join crhd on afru.arbid = crhd.objid

    left outer join qals on afru.aufnr = qals.aufnr

    left outer join qamv on qals.prueflos = qamv.prueflos

    left outer join qamr on qals.prueflos = qamr.prueflos
{
  key afru.rueck                           as Confirmation_No,
  key afru.rmzhl                           as Confirmation_Counter,

      afru.werks                           as Plant,
      afru.budat                           as Posting_Date,
      afru.ersda                           as Document_Date,
      afru.kaptprog                        as Shift,

      crhd.arbpl                           as WorkCenter,

      afru.aufnr                           as Production_Order,
      aufk.auart                           as Order_Type,
      afru.meinh                           as UoM,
      //@Semantics.quantity.unitOfMeasure: 'UoM'
      //afru.lmnga as ConfirmedYield,
      //
      //     // afru.lmnga                            as ConfirmedYield,
      //     @Semantics.quantity.unitOfMeasure: 'UoM'
      //afru.xmnga as ConfirmedScrap,
      //    //  afru.xmnga                            as ConfirmedScrap,

      cast( afru.lmnga as abap.dec(15,3) ) as Confirmed_Yield,

      cast( afru.xmnga as abap.dec(15,3) ) as Confirmed_Scrap,

      cast(
           afru.lmnga - afru.xmnga
           as abap.dec(15,3)
      )                                    as Good_Production_Qty,

      cast(
           afpo.psmng - afru.lmnga
           as abap.dec(15,3)
      )                                    as Pending_Qty,

      qamv.sollwert                        as Std_Cycle_Time,

      qamr.original_input                  as Act_Cycle_Time,

      // qamv.sollwert                         as StdWeight,

      qamr.original_input                  as Actual_Weight,

      //            cast(
      //                 ( qamv.sollwert * afru.lmnga ) / 1000
      //                 as abap.fltp
      //            ) as TotalProductionKG,
      cast(
         ( cast( qamv.sollwert as abap.dec(15,3) )
           * cast( afru.lmnga as abap.dec(15,3) ) ) / 1000
         as abap.dec(15,3)
      )                                    as TotalProductionKG,

      //      cast(
      //           ( qamv.sollwert * afru.xmnga ) / 1000
      //           as abap.dec(15,3)
      //      )                                     as ScrapWeightKG,

      cast(
      ( cast( qamv.sollwert as abap.dec(15,3) )
      * cast( afru.xmnga as abap.dec(15,3) ) ) / 1000
      as abap.dec(15,3)
      )                                    as Scrap_Weight,



      cast( afru.ism03 as abap.dec(15,3) ) as Machine_Time
}
where
      afru.budat = $parameters.p_date
  and
  //crhd.arbpl =$parameters.p_work
  // and
      afru.aufnr = $parameters.p_order
  //and
  //afpo.matnr = $parameters.p_material
