@AbapCatalog.viewEnhancementCategory: [#NONE]
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'First CDS View'
@Metadata.ignorePropagatedAnnotations: true
define view entity zfirst_cds11 
as select from mara
//association [0..*] to marc as _plant
//on mara.matnr = _plant.matnr
{
    key  matnr as Material,
    ernam as Created_By,
    ersda as Created_On,
    mtart as Material_Type,
    matkl as Material_Group
//    _plant
    
    } where mtart = 'FERT'








//*&---------------------------------------------------------------------*
//*& CDS conversion of ZPURCHASE_REGISTER -> P2 (2nd radiobutton) logic  *
//*& Source ABAP form: PROCESS_DATA_ALL, ELSEIF p2 IS NOT INITIAL block  *
//*&---------------------------------------------------------------------*
//* Mapping notes (ABAP -> CDS):
//*   - ACDOCA select (bukrs/gjahr/lifnr/budat filter) + BKPF (blart IN
//*     KR/KG/KA)                 -> ZI_PurchRegDoc (basic/header view)
//*   - LV_SHKZG derivation (based on BLART + XREVERSAL)
//*                                -> DerivedShkzg calculated field
//*   - Final sign flip (*-1) loop at the very end
//*                                -> SignMultiplier calculated field
//*   - BSEG detail line (BUZID = '' , SHKZG = LV_SHKZG)
//*                                -> association _MainLine
//*   - BSEG tax line (BUZID = 'T'), read twice (once with LV_SHKZG,
//*     once forced to 'H', 2nd overwrites 1st when it exists)
//*                                -> _TaxLineDyn / _TaxLineH + COALESCE
//*   - BSEG (BUZID = '' , SHKZG = 'H') summed into GROSS
//*                                -> ZI_PurchRegGrossSum (aggregation)
//*   - BSET loop -> CGST/SGST/IGST rate & amount, taxable value
//*                                -> ZI_PurchRegTaxAmounts (aggregation)
//*   - FAGLFLEXA fallback for PRCTR / GSBER
//*                                -> _FaglFlexA (substring match on DOCLN)
//*   - MARC-STEUC (HSN) fallback to BKPF-BKTXT
//*                                -> COALESCE(Marc.Steuc, Bkpf.Bktxt)
//*   - Vendor lookup (BSEG KOART = 'K') + LFA1 with STCD1/STCD2/STCD3
//*     fallback chain for VAT number
//*                                -> _VendorLine, _Vendor, COALESCE chain
//*   - T005U region text (via T001-LAND1 + LFA1-REGIO)
//*                                -> _CompanyCode, _Region
//*   - SO_LIFNR / SO_GSBER selection screen filters
//*                                -> left to the consuming report/ALV
//*
//* NOT fully representable in a flat CDS (documented, not silently
//* dropped):
//*   - The original code re-reads BSEG buzid='' shkzg='H' in an
//*     UNRESTRICTED loop (not limited to the current line) and keeps
//*     adding onto GROSS. ZI_PurchRegGrossSum reproduces this as a
//*     document-level SUM(DMBTR), joined 1:1 into every detail row of
//*     that document - this is very likely the intended result, but if
//*     the legacy report was in fact (accidentally) accumulating GROSS
//*     per detail-line-iteration instead of per-document, the numbers
//*     will differ. Test against the ABAP report before go-live.
//*&---------------------------------------------------------------------*


//"===============================================================
//" 1) Header/Basic view: BKPF + ACDOCA (existence used only as a
