// Z_I_MAINT_COST - grain: Universal Journal line (ACDOCA) posted to a maintenance order.
// COEP is a compatibility view in S/4HANA; ACDOCA holds the actual CO line items.
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'ABC: Maintenance Cost Fact (ACDOCA)'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@Analytics.dataCategory: #FACT
@Analytics.dataExtraction.enabled: true
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #XXL, dataClass: #TRANSACTIONAL }
define view entity ZI_ABC_MaintCostFact
  as select from acdoca
    inner join      aufk on  aufk.aufnr = acdoca.aufnr
                         and aufk.autyp = '30'
    inner join      afih on  afih.aufnr = acdoca.aufnr
    left outer join cskt on  cskt.spras = $session.system_language
                         and cskt.kokrs = acdoca.kokrs
                         and cskt.kostl = acdoca.rcntr
                         and cskt.datbi = '99991231'
{
  key acdoca.rldnr  as Ledger,                          // RLDNR
  key acdoca.rbukrs as CompanyCode,                     // RBUKRS
  key acdoca.gjahr  as FiscalYear,                      // GJAHR
  key acdoca.belnr  as CostDocument,                    // BELNR
  key acdoca.docln  as CostDocumentItem,                // DOCLN
      acdoca.aufnr  as MaintenanceOrder,                // AUFNR
      aufk.auart    as OrderType,                       // AUART
      afih.equnr    as Equipment,                       // EQUNR (order's equipment)
      acdoca.budat  as PostingDate,                     // BUDAT
      acdoca.poper  as FiscalPeriod,                    // POPER
      acdoca.racct  as CostElement,                     // RACCT
      acdoca.rcntr  as CostCenter,                      // RCNTR
      cskt.ktext    as CostCenterName,                  // KTEXT
      acdoca.werks  as Plant,                           // WERKS
      acdoca.rhcur  as Currency,                        // RHCUR (company code currency)
      cast( acdoca.hsl as abap.dec(23,2) ) as Amount   // HSL (signed)
}
where acdoca.rldnr = '0L'            // leading ledger
  and acdoca.awtyp <> 'AUAK'         // exclude order settlement (would cancel the cost)
