// Helper: PM order confirmations (AFRU) -> actual work hours per maintenance order
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'ABC: Actual Work Hours per Maint. Order'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@ObjectModel.usageType: { serviceQuality: #B, sizeCategory: #L, dataClass: #TRANSACTIONAL }
define view entity ZI_ABC_OrderWorkAgg
  as select from afru
{
  key afru.aufnr as MaintenanceOrder,                                   // AUFNR
      // ISMNW converted to hours by its unit ISMNE (H / MIN / TAG = day)
      cast( sum( case afru.ismne
                   when 'MIN' then division( cast( afru.ismnw as abap.dec(13,3) ), 60, 3 )
                   when 'TAG' then cast( afru.ismnw as abap.dec(13,3) ) * 24
                   else            cast( afru.ismnw as abap.dec(13,3) ) end )
            as abap.dec(15,2) )                                          as ActualWorkHours,
      count(*)                                                           as ConfirmationCount
}
where afru.stokz = ''                 // not reversed
  and afru.stzhl = '00000000'         // not a cancellation record
  and afru.aufnr <> ''
group by afru.aufnr
