@Analytics.dataCategory: #FACT
@EndUserText.label: 'AR Open Items - Interface View (ACDOCA)'

define view ZI_AROpenItems
  as select from acdoca
  left outer join bseg
    on  bseg.bukrs = acdoca.rbukrs
    and bseg.belnr = acdoca.belnr
    and bseg.gjahr = acdoca.gjahr
    and bseg.buzei = acdoca.buzei

  association [1..1] to ZI_ARCustomerMaster as _Customer
    on  _Customer.Customer    = acdoca.kunnr
    and _Customer.CompanyCode = acdoca.rbukrs

  association [1..1] to ZI_ARCompanyCode as _CompanyCode
    on  _CompanyCode.CompanyCode = acdoca.rbukrs

{
  // ---------------------------------------------------------
  // Keys
  // ---------------------------------------------------------
  key acdoca.rclnt             as Client,
  key acdoca.rbukrs            as CompanyCode,
  key acdoca.gjahr             as FiscalYear,
  key acdoca.belnr             as AccountingDocument,
  key acdoca.docln             as LineItem,
  key acdoca.budat             as PostingDate,

  // ---------------------------------------------------------
  // Document identification
  // ---------------------------------------------------------
  @EndUserText.label: 'Document Type'
  acdoca.blart                 as DocumentType,

  @EndUserText.label: 'Posting Key'
  acdoca.bschl                 as PostingKey,

  @EndUserText.label: 'Customer'
  acdoca.kunnr                 as Customer,

  @EndUserText.label: 'Account Type'
  acdoca.koart                 as AccountType,

  @EndUserText.label: 'Special GL Indicator'
  acdoca.umskz                 as SpecialGLIndicator,

  @EndUserText.label: 'Assignment'
  acdoca.zuonr                 as AssignmentNumber,

  @EndUserText.label: 'Document Status'
  acdoca.bstat                 as DocumentStatus,

  @EndUserText.label: 'Debit/Credit Indicator'
  acdoca.drcrk                 as DebitCreditIndicator,

  // ---------------------------------------------------------
  // Clearing
  // ---------------------------------------------------------
  @EndUserText.label: 'Clearing Document'
  acdoca.augbl                 as ClearingDocument,

  @EndUserText.label: 'Clearing Date'
  acdoca.augdt                 as ClearingDate,

  @EndUserText.label: 'Clearing Fiscal Year'
  acdoca.auggj                 as ClearingFiscalYear,

  // ---------------------------------------------------------
  // Dates
  // ---------------------------------------------------------
  @EndUserText.label: 'Document Date'
  acdoca.bldat                 as DocumentDate,

  @EndUserText.label: 'Net Due Date'
  acdoca.netdt                 as DueDate,

  @EndUserText.label: 'Baseline Date'
  bseg.zfbdt                   as BaselineDate,

  @EndUserText.label: 'Payment Terms'
  bseg.zterm                   as PaymentTerms,

  // ---------------------------------------------------------
  // Dunning (from BSEG)
  // ---------------------------------------------------------
  //@EndUserText.label: 'Dunning Level'
 // bseg.mahns                   as DunningLevel,

  @EndUserText.label: 'Dunning Date'
  bseg.madat                   as DunningDate,

  @EndUserText.label: 'Dunning Block'
  bseg.mansp                   as DunningBlock,

  //@EndUserText.label: 'Reference Document'
 // bseg.xblnr                   as ReferenceDocument,

  // ---------------------------------------------------------
  // Amounts and Currencies
  // ---------------------------------------------------------
  @EndUserText.label: 'Company Code Currency'
  @Semantics.currencyCode: true
  acdoca.rhcur                 as CurrencyLC,

  @EndUserText.label: 'Transaction Currency'
  @Semantics.currencyCode: true
  acdoca.rwcur                 as CurrencyTC,

  @EndUserText.label: 'Amount in Company Code Currency'
  @Semantics.amount.currencyCode: 'CurrencyLC'
  acdoca.hsl                   as AmountLC,

  @EndUserText.label: 'Amount in Transaction Currency'
  @Semantics.amount.currencyCode: 'CurrencyTC'
  acdoca.wsl                   as AmountTC,

  // ---------------------------------------------------------
  // Calculated: net due days (+ = overdue, - = not yet due)
  // ---------------------------------------------------------
  @EndUserText.label: 'Net Due Days'
  cast(
    dats_days_between(
      acdoca.netdt,
      cast( $session.system_date as dats )
    ) as int4
  )                            as NetDueDays,

  // ---------------------------------------------------------


  // ---------------------------------------------------------
  // Associations (navigated by upper layers)
  // ---------------------------------------------------------
  _Customer,
  _CompanyCode

}
where
      acdoca.koart = 'D'
  and acdoca.bstat = ' '
