@EndUserText.label: 'UC15 GST rates per billing item'
define view entity ZI_GST_OUT_TAX
  as select from prcd_elements
{
  key knumv,
  key kposn,
  sum( case when kschl = 'JOCG'
            then cast( kbetr as abap.dec(24,9) )
            else cast( 0 as abap.dec(24,9) ) end ) as cgst_rate,
  sum( case when kschl = 'JOSG' or kschl = 'JOUG'   -- UTGST folded into SGST
            then cast( kbetr as abap.dec(24,9) )
            else cast( 0 as abap.dec(24,9) ) end ) as sgst_rate,
  sum( case when kschl = 'JOIG'
            then cast( kbetr as abap.dec(24,9) )
            else cast( 0 as abap.dec(24,9) ) end ) as igst_rate,
  sum( case when kschl = 'ZCES'                     -- replace with your cess condition
            then cast( kbetr as abap.dec(24,9) )
            else cast( 0 as abap.dec(24,9) ) end ) as cess_rate
}
where kinak = ''
group by knumv, kposn
