define view entity ZI_MYQ_OrderConfAgg
  as select from ZI_MYQ_ProdConfirmationFact
{
  key ProductionOrder,
      // Yield counted at the last operation only (otherwise counted once per operation)
      cast( sum( case when IsLastOperation = 1 then ConfirmedYieldQuantity
                      else cast( 0 as abap.dec(15,3) ) end ) as abap.dec(15,3) ) as YieldQuantity,
      cast( sum( ConfirmedScrapQuantity )  as abap.dec(15,3) ) as ScrapQuantity,
      cast( sum( ConfirmedReworkQuantity ) as abap.dec(15,3) ) as ReworkQuantity,
      max( IsUnitDifferentFromOrder )                          as HasUnitMismatch,
      count(*)                                                 as ConfirmationCount
}
group by ProductionOrder
