// Helper: billing items -> 1 row per sales order item (credit memos/cancellations netted)
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'O2C: Billing per Sales Order Item'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #L, dataClass: #TRANSACTIONAL }
@Analytics.dataCategory: #FACT
@Analytics.dataExtraction.enabled: true

define view entity ZI_O2C_BillingAgg
  as select from ZI_O2C_BillingItem
{
  key SalesOrder,
  key SalesOrderItem,
      max( ValidInvoice )     as LatestBillingDocument,
      min( BillingDate )      as FirstBillingDate,
      max( BillingDate )      as LastBillingDate,
      max( RevenueCategory )  as RevenueCategory,
      count( distinct BillingDocument ) as BillingDocumentCount,
      cast( sum( case when SignFactor = -1 then BilledQuantity * -1 else BilledQuantity end )
            as abap.dec(15,3) )                                          as InvoicedQuantity,
      cast( sum( case when SignFactor = -1 then NetValue * -1 else NetValue end )
            as abap.dec(17,2) )                                          as BilledNetValue,
      cast( sum( case when SignFactor = -1 then NetValueInCCCrcy * -1 else NetValueInCCCrcy end )
            as abap.dec(17,2) )                                          as RevenueInCCCrcy,
      cast( sum( ARAmountInCCCrcy )   as abap.dec(17,2) )                as ARAmountInCCCrcy,
      cast( sum( OpenAmountInCCCrcy ) as abap.dec(17,2) )                as OpenAmountInCCCrcy
}
where SalesOrder <> ''
group by SalesOrder, SalesOrderItem
