// Billing item (VBRK/VBRP) with revenue converted to company code currency and
// the invoice's FI amount allocated to the item by its share of the invoice net value.
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'O2C: Billing Item with AR Allocation'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #XL, dataClass: #TRANSACTIONAL }
@Analytics.dataCategory: #FACT
@Analytics.dataExtraction.enabled: true
@Analytics.dataExtraction.delta.changeDataCapture.automatic: true
define view entity ZI_O2C_BillingItem
  as select from vbrp
    inner join      vbrk                    on vbrk.vbeln = vbrp.vbeln
    inner join      t001                    on t001.bukrs = vbrk.bukrs
    left outer join ZI_O2C_InvoiceAR as AR  on AR.BillingDocument = vbrp.vbeln
{
  key vbrp.vbeln  as BillingDocument,                   // VBELN
  key vbrp.posnr  as BillingDocumentItem,               // POSNR
      vbrp.aubel  as SalesOrder,                        // AUBEL
      vbrp.aupos  as SalesOrderItem,                    // AUPOS
      vbrk.vbtyp  as SDDocumentCategory,                // VBTYP
      vbrk.fkdat  as BillingDate,                       // FKDAT
      vbrk.fksto  as IsCancelled,                       // FKSTO
      vbrp.ktgrm  as RevenueCategory,                   // KTGRM (acct assignment group material)
      case when vbrk.vbtyp = 'N' or vbrk.vbtyp = 'O' then -1 else 1 end  as SignFactor,

      // Only real, non-cancelled invoices can be the "latest invoice"
      case when vbrk.vbtyp = 'M' and vbrk.fksto = '' then vbrp.vbeln end as ValidInvoice,

      cast( vbrp.fkimg as abap.dec(15,3) )  as BilledQuantity,           // FKIMG (unsigned)
      cast( vbrp.netwr as abap.dec(17,2) )  as NetValue,                 // NETWR, doc currency (unsigned)
      vbrk.waerk  as TransactionCurrency,
      t001.waers  as CompanyCodeCurrency,
      cast( currency_conversion( amount             => vbrp.netwr,
                                 source_currency    => vbrk.waerk,
                                 target_currency    => t001.waers,
                                 exchange_rate_date => vbrk.fkdat,
                                 exchange_rate_type => 'M',
                                 error_handling     => 'SET_TO_NULL' ) as abap.dec(17,2) ) as NetValueInCCCrcy,  // unsigned

      // FI amounts (already signed by FI) x item share of invoice
      cast( case when vbrk.netwr <> 0 and AR.BillingDocument is not null
                 then cast( division( cast( vbrp.netwr as abap.dec(17,2) ),
                                      cast( vbrk.netwr as abap.dec(17,2) ), 6 ) as abap.dec(9,6) )
                      * AR.AmountInCCCrcy
                 else cast( 0 as abap.dec(17,2) ) end as abap.dec(17,2) )              as ARAmountInCCCrcy,
      cast( case when vbrk.netwr <> 0 and AR.BillingDocument is not null
                 then cast( division( cast( vbrp.netwr as abap.dec(17,2) ),
                                      cast( vbrk.netwr as abap.dec(17,2) ), 6 ) as abap.dec(9,6) )
                      * AR.OpenAmountInCCCrcy
                 else cast( 0 as abap.dec(17,2) ) end as abap.dec(17,2) )              as OpenAmountInCCCrcy
}
where ( vbrk.vbtyp = 'M' or vbrk.vbtyp = 'N' or vbrk.vbtyp = 'O'
     or vbrk.vbtyp = 'P' or vbrk.vbtyp = 'S' )
