// Customer line items of FI documents (BKPF/BSEG, KOART = D). Replaces BSID/BSAD
// (compatibility views in S/4HANA). AUGBL empty = open (BSID), filled = cleared (BSAD).
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'O2C: Customer AR Line Item (BKPF/BSEG)'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #BASIC
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #XXL, dataClass: #TRANSACTIONAL }
@Analytics.dataCategory: #FACT
@Analytics.dataExtraction.enabled: true
@Analytics.dataExtraction.delta.changeDataCapture.automatic: true
define view entity ZI_O2C_CustomerARItem
  as select from bseg
    inner join   bkpf on  bkpf.bukrs = bseg.bukrs
                      and bkpf.belnr = bseg.belnr
                      and bkpf.gjahr = bseg.gjahr
{
  key bseg.bukrs  as CompanyCode,                       // BUKRS
  key bseg.belnr  as AccountingDocument,                // BELNR
  key bseg.gjahr  as FiscalYear,                        // GJAHR
  key bseg.buzei  as AccountingDocumentItem,            // BUZEI
      bseg.kunnr  as Customer,                          // KUNNR
      bkpf.awtyp  as ReferenceTransaction,              // AWTYP (VBRK = billing)
      cast( substring( bkpf.awkey, 1, 10 ) as abap.char(10) ) as BillingDocument,  // AWKEY -> VBRK-VBELN
      bkpf.blart  as DocumentType,                      // BLART
      bkpf.budat  as PostingDate,                       // BUDAT
      bkpf.bldat  as DocumentDate,                      // BLDAT
      bkpf.hwaer  as CompanyCodeCurrency,               // HWAER
      bseg.shkzg  as DebitCreditCode,                   // SHKZG
      bseg.zterm  as PaymentTerms,                      // ZTERM
      bseg.zfbdt  as BaselineDate,                      // ZFBDT
      bseg.augdt  as ClearingDate,                      // AUGDT
      bseg.augbl  as ClearingDocument,                  // AUGBL
      bseg.manst  as DunningLevel,                      // MANST
      bseg.madat  as LastDunnedDate,                    // MADAT

      // Net due date = baseline + longest cash-discount/net period
      case when bseg.zbd3t > 0 then dats_add_days( bseg.zfbdt, cast( bseg.zbd3t as abap.int4 ), 'INITIAL' )
           when bseg.zbd2t > 0 then dats_add_days( bseg.zfbdt, cast( bseg.zbd2t as abap.int4 ), 'INITIAL' )
           else                     dats_add_days( bseg.zfbdt, cast( bseg.zbd1t as abap.int4 ), 'INITIAL' )
      end                                                                      as NetDueDate,

      // Signed amount in company code currency (credit = negative)
      cast( case bseg.shkzg when 'H' then cast( bseg.dmbtr as abap.dec(17,2) ) * -1
                            else          cast( bseg.dmbtr as abap.dec(17,2) ) end
            as abap.dec(17,2) )                                                as AmountInCCCrcy,
      cast( case when bseg.augbl <> '' then cast( 0 as abap.dec(17,2) )
                 when bseg.shkzg = 'H' then cast( bseg.dmbtr as abap.dec(17,2) ) * -1
                 else                       cast( bseg.dmbtr as abap.dec(17,2) ) end
            as abap.dec(17,2) )                                                as OpenAmountInCCCrcy,
      case when bseg.augbl = '' then 1 else 0 end                              as IsOpen,

      // Payment behaviour: days paid after net due date (cleared invoices only)
      case when bseg.augbl <> '' and bseg.shkzg = 'S' then 1 else 0 end        as IsClearedInvoice,
      case when bseg.augbl <> '' and bseg.shkzg = 'S'
           then dats_days_between( bseg.zfbdt, bseg.augdt )
              - cast( case when bseg.zbd3t > 0 then bseg.zbd3t
                           when bseg.zbd2t > 0 then bseg.zbd2t
                           else                     bseg.zbd1t end as abap.int4 )
           else 0 end                                                          as DaysPaidLate
}
where bseg.koart = 'D'          // customer lines
  and bkpf.bstat = ''           // normal documents (no noted/parked items)
