// Customer credit (FSCM Credit Management) - 1 row per customer.
// Customer -> Business Partner via CVI_CUST_LINK / BUT000.
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'O2C: Customer Credit'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #M, dataClass: #MASTER }
@Analytics.dataCategory: #FACT
@Analytics.dataExtraction.enabled: true
@Analytics.dataExtraction.delta.changeDataCapture.automatic: true
define view entity ZI_O2C_CustomerCredit
  as select from kna1
    left outer join cvi_cust_link                   on  cvi_cust_link.customer = kna1.kunnr
    left outer join but000                          on  but000.partner_guid = cvi_cust_link.partner_guid
    left outer join ukmbp_cms                       on  ukmbp_cms.partner = but000.partner
    left outer join ukmbp_cms_sgm                   on  ukmbp_cms_sgm.partner      = but000.partner
                                                    and ukmbp_cms_sgm.credit_sgmnt = '0000'   // ASSUMPTION: main credit segment
    left outer join ZI_O2C_CustomerARSummary as ARS on  ARS.Customer = kna1.kunnr
{
  key kna1.kunnr                    as Customer,
      but000.partner                as BusinessPartner,
      ukmbp_cms.risk_class          as RiskClass,              // RISK_CLASS
      ukmbp_cms.check_rule          as CreditCheckRule,        // CHECK_RULE
      ukmbp_cms.credit_group        as CreditGroup,            // CREDIT_GROUP
      ukmbp_cms_sgm.xblocked        as IsCreditBlocked,        // XBLOCKED
      coalesce( cast( ukmbp_cms_sgm.credit_limit as abap.dec(17,2) ), cast( 0 as abap.dec(17,2) ) ) as CreditLimit,   // CREDIT_LIMIT
      // Exposure approximated as open receivables (see notes)
      coalesce( ARS.OpenReceivables, cast( 0 as abap.dec(17,2) ) )       as CreditExposure,
      cast( case when ukmbp_cms_sgm.credit_limit > 0
                 then division( coalesce( ARS.OpenReceivables, cast( 0 as abap.dec(17,2) ) ) * 100,
                                cast( ukmbp_cms_sgm.credit_limit as abap.dec(17,2) ), 2 )
                 else cast( 0 as abap.dec(11,2) ) end as abap.dec(11,2) ) as CreditUtilizationPercent,
      cast( case when ARS.ClearedInvoiceCount > 0
                 then division( ARS.TotalDaysPaidLate, ARS.ClearedInvoiceCount, 1 )
                 else cast( 0 as abap.dec(9,1) ) end as abap.dec(9,1) )  as AvgPaymentDelayDays
}
