@AbapCatalog.sqlViewName: 'ZV_OEE_CALC1'
@EndUserText.label: 'OEE Calculation'
@AccessControl.authorizationCheck: #NOT_REQUIRED
 
define view ZI_OEE_CALC1
as select from ZI_OEE_FINAL as A
{
    key A.WorkCenter,
    key A.aufnr,
    key A.vornr,
 
    A.TotalPieces,
    A.GoodPieces,
    A.ActualTime,
    A.PPT,
    A.StdCycle,
 
    /* ============================ */
    /* Operating Time */
    /* ============================ */
    cast( A.PPT as abap.fltp )
      - cast( A.ActualTime as abap.fltp )
        as OperatingTime,
 
    /* ============================ */
    /* Availability % */
    /* ============================ */
    case
        when A.PPT = 0 then 0
        else
            (
                cast( A.PPT as abap.fltp )
                - cast( A.ActualTime as abap.fltp )
            )
            / cast( A.PPT as abap.fltp )
            * 100.0
    end as AvailabilityPct,
 
    /* ============================ */
    /* Performance % */
    /* ============================ */
    case
        when A.PPT = A.ActualTime then 0
        else
            (
                cast( A.StdCycle as abap.fltp )
                * cast( A.TotalPieces as abap.fltp )
            )
            /
            (
                cast( A.PPT as abap.fltp )
                - cast( A.ActualTime as abap.fltp )
            )
            * 100.0
    end as PerformancePct,
 
    /* ============================ */
    /* Quality % */
    /* ============================ */
    case
        when A.TotalPieces = 0 then 0
        else
            cast( A.GoodPieces as abap.fltp )
            / cast( A.TotalPieces as abap.fltp )
            * 100.0
    end as QualityPct,
 
    /* ============================ */
    /* OEE */
    /* ============================ */
    case
        when A.PPT = 0 
          or A.TotalPieces = 0 
          or A.PPT = A.ActualTime then 0
        else
            (
                (
                    cast( A.PPT as abap.fltp )
                    - cast( A.ActualTime as abap.fltp )
                )
                / cast( A.PPT as abap.fltp )
            )
            *
            (
                (
                    cast( A.StdCycle as abap.fltp )
                    * cast( A.TotalPieces as abap.fltp )
                )
                /
                (
                    cast( A.PPT as abap.fltp )
                    - cast( A.ActualTime as abap.fltp )
                )
            )
            *
            (
                cast( A.GoodPieces as abap.fltp )
                / cast( A.TotalPieces as abap.fltp )
            )
            * 100.0
    end as OEE
}
