@EndUserText.label: 'OEE Confirmations'
 
define view ZI_OEE_CONF
as select from afru as A
 
inner join crhd as C
  on A.arbid = C.objid
 
{
  C.arbpl as WorkCenter,
  A.aufnr,
  A.vornr,
 
/* Total Pieces */
sum( A.gmnga ) + sum( A.xmnga ) + sum( A.rmnga ) as TotalPieces,
 
/* Good Pieces */
sum( A.gmnga ) - sum( A.xmnga ) - sum( A.rmnga ) as GoodPieces,
 
/* Actual Time */
sum( A.ismnw ) as ActualTime,
 
/* Setup Time */
sum( A.ismnw ) as ActualSetup
 
}
group by
  C.arbpl,
  A.aufnr,
  A.vornr
