// Helper: one row per accounting document (leading ledger).
// Gives document balance and the supplier / clearing data from the vendor
// line, so every line of the document can carry them.
// OPEX classification is done in Datasphere (mapping table), not here.
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'OPEX: Accounting Document Summary'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #XL, dataClass: #TRANSACTIONAL }
define view entity ZI_OPX_DocumentSummary
  as select from acdoca
{
  key acdoca.rbukrs as CompanyCode,
  key acdoca.gjahr  as FiscalYear,
  key acdoca.belnr  as AccountingDocument,
      cast( sum( cast( acdoca.hsl as abap.dec(23,2) ) ) as abap.dec(23,2) ) as DocumentNetAmount,
      // Expense lines = G/L accounts in the expense range (CONFIRM RANGE WITH FINANCE)
      sum( case when acdoca.racct between '0000600000' and '0000699999' then 1 else 0 end ) as ExpenseLineCount,
      count(*)                                                               as DocumentLineCount,
      // Supplier and payment data from the vendor (K) line
      max( case when acdoca.koart = 'K' then acdoca.lifnr end )  as Supplier,
      max( case when acdoca.koart = 'K' then acdoca.netdt end )  as NetDueDate,
      max( case when acdoca.koart = 'K' then acdoca.augdt end )  as ClearingDate,
      max( case when acdoca.koart = 'K' then acdoca.augbl end )  as ClearingDocument,
      max( case when acdoca.koart = 'K' then acdoca.racct end )  as PayablesAccount
}
where acdoca.rldnr = '0L'
  and acdoca.gjahr >= '2024'         // spec period 2024 onwards - keeps the aggregation small
group by acdoca.rbukrs, acdoca.gjahr, acdoca.belnr
