// Grain control: vendor AP lines (1..n per invoice) -> 1 row per supplier invoice
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PSC: AP Status per Supplier Invoice'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #L, dataClass: #TRANSACTIONAL }
define view entity ZI_PSC_InvoiceAPStatus
  as select from ZI_PSC_VendorAPItem
{
  key InvoiceSortKey,                                      // GJAHR + BELNR of RBKP
      SupplierInvoice,
      SupplierInvoiceFiscalYear,
      max( PaymentBaselineDate ) as PaymentBaselineDate,   // ZFBDT
      max( PaymentTerms )        as APPaymentTerms,        // ZTERM
      max( ClearingDate )        as ClearingDate,          // AUGDT
      sum( case when ClearingAccountingDocument = '' then 1 else 0 end ) as OpenVendorLineCount,
            count(*)                   as VendorLineCount,
      cast( sum( DiscountBaseAmount ) as abap.dec(17,2) ) as DiscountBaseAmount,
      cast( sum( CashDiscountAmount ) as abap.dec(17,2) ) as CashDiscountAvailable,
      // Taken = invoice cleared on or before the cash discount due date
      cast( sum( case when ClearingAccountingDocument <> '' and ClearingDate <= CashDiscountDueDate
                      then CashDiscountAmount else cast( 0 as abap.dec(17,2) ) end ) as abap.dec(17,2) ) as CashDiscountTaken
}
group by InvoiceSortKey, SupplierInvoice, SupplierInvoiceFiscalYear
