@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PSC: PO History / GR-IR Events (EKBE)'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #BASIC
@ObjectModel.usageType: { serviceQuality: #B, sizeCategory: #XL, dataClass: #TRANSACTIONAL }
define view entity ZI_PSC_POHistory
  as select from ekbe
{
  key ebeln as PurchaseOrder,                  // EBELN
  key ebelp as PurchaseOrderItem,              // EBELP
  key zekkn as AccountAssignmentNumber,        // ZEKKN
  key vgabe as PurchasingHistoryCategory,      // VGABE (1 = GR, 2 = IR)
  key gjahr as ReferenceDocumentFiscalYear,    // GJAHR
  key belnr as ReferenceDocument,              // BELNR (material/invoice doc)
  key buzei as ReferenceDocumentItem,          // BUZEI
      bewtp as PurchasingHistoryType,          // BEWTP
      bwart as GoodsMovementType,              // BWART
      budat as PostingDate,                    // BUDAT
      shkzg as DebitCreditCode,                // SHKZG (S = receipt, H = reversal/return)
      waers as DocumentCurrency,               // WAERS

      // Signed values: reversals (102/122 etc.) net off the receipt
      cast( case shkzg when 'H' then cast( menge as abap.dec(15,3) ) * -1
                       else          cast( menge as abap.dec(15,3) ) end
            as abap.dec(15,3) )                                  as SignedQuantity,
      cast( case shkzg when 'H' then cast( wrbtr as abap.dec(17,2) ) * -1
                       else          cast( wrbtr as abap.dec(17,2) ) end
            as abap.dec(17,2) )                                  as SignedAmount,

      // Only a positive GR posting counts as a receipt date
      case when vgabe = '1' and shkzg = 'S' then budat end       as ReceiptPostingDate
}
