// Grain control: RSEG lines (0..n per PO item) -> 1 row per PO item.
// Each invoice line's value is booked as Open or Cleared by its invoice's
// AP status, so one FI vendor line is never repeated across PO items.
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PSC: Invoice & AP at PO Item Grain'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #L, dataClass: #TRANSACTIONAL }
define view entity ZI_PSC_POInvoiceAgg
  as select from ZI_PSC_SupplierInvoiceItem as InvItem
    left outer join ZI_PSC_InvoiceAPStatus as AP
      on AP.InvoiceSortKey = InvItem.InvoiceDocumentKey
{
  key InvItem.PurchaseOrder,
  key InvItem.PurchaseOrderItem,
      cast( sum( InvItem.SignedAmount )   as abap.dec(17,2) ) as InvoiceAmount,
      cast( sum( InvItem.SignedQuantity ) as abap.dec(15,3) ) as InvoiceQuantity,
      cast( sum( case when AP.OpenVendorLineCount > 0
                      then InvItem.SignedAmount
                      else cast( 0 as abap.dec(17,2) ) end ) as abap.dec(17,2) ) as APOpenAmount,
      cast( sum( case when AP.OpenVendorLineCount = 0
                      then InvItem.SignedAmount
                      else cast( 0 as abap.dec(17,2) ) end ) as abap.dec(17,2) ) as APClearedAmount,
      max( InvItem.InvoiceSortKey )          as LatestInvoiceSortKey,
      max( InvItem.ValidInvoicePostingDate ) as InvoicePostingDate,
            count( distinct InvItem.SupplierInvoice ) as InvoiceDocumentCount,
      sum( InvItem.IsBlockedLine )               as BlockedInvoiceLineCount,
      max( InvItem.PaymentBlockReason )          as PaymentBlockReason,
      cast( sum( case when AP.InvoiceSortKey is not null
                      then InvItem.InvoiceShare * AP.DiscountBaseAmount
                      else cast( 0 as abap.dec(17,2) ) end ) as abap.dec(17,2) ) as DiscountBaseAmount,
      cast( sum( case when AP.InvoiceSortKey is not null
                      then InvItem.InvoiceShare * AP.CashDiscountTaken
                      else cast( 0 as abap.dec(17,2) ) end ) as abap.dec(17,2) ) as CashDiscountTaken
}
where InvItem.SupplierInvoiceStatus = '5'
group by InvItem.PurchaseOrder, InvItem.PurchaseOrderItem
