// Final fact: FACT_PROCUREMENT_SPEND. Grain: EBELN + EBELP.
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PSC: Procurement Spend Fact'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #COMPOSITE
@Analytics.dataCategory: #FACT
@Analytics.dataExtraction.enabled: true
@ObjectModel.usageType: { serviceQuality: #D, sizeCategory: #XL, dataClass: #MIXED }
define view entity ZI_PSC_ProcurementSpend
  as select from ZI_PSC_ProcSpendBase as B
{
      // ===== Spec fields (Appendix A) ========================================
      @EndUserText.label: 'Purchase Order (EBELN)'
  key B.PurchaseOrder,
      @EndUserText.label: 'PO Item (EBELP)'
  key B.PurchaseOrderItem,
      @EndUserText.label: 'Vendor (LIFNR)'
      B.Supplier,
      @EndUserText.label: 'Vendor Name (NAME1)'
      B.SupplierName,
      @EndUserText.label: 'Vendor Country (LAND1)'
      B.SupplierCountry,
      @EndUserText.label: 'Company Code (BUKRS)'
      B.CompanyCode,
      @EndUserText.label: 'Vendor Std Payment Terms (LFB1-ZTERM)'
      B.VendorPaymentTerms,
      @EndUserText.label: 'Reconciliation Account (AKONT)'
      B.ReconciliationAccount,
      @EndUserText.label: 'Purchasing Org (EKORG)'
      B.PurchasingOrganization,
      @EndUserText.label: 'Vendor Order Currency (LFM1-WAERS)'
      B.SupplierOrderCurrency,
      @EndUserText.label: 'PO Date (BEDAT)'
      B.PurchaseOrderDate,
      @EndUserText.label: 'Fiscal Year'
      B.FiscalYear,
      @EndUserText.label: 'Fiscal Quarter'
      cast( case when B.FiscalPeriod is null   then ''
                 when B.FiscalPeriod <= '003'  then '1'
                 when B.FiscalPeriod <= '006'  then '2'
                 when B.FiscalPeriod <= '009'  then '3'
                 else                               '4' end as abap.char(1) ) as FiscalQuarter,
      @EndUserText.label: 'Fiscal Month (Period)'
      B.FiscalPeriod,
      @EndUserText.label: 'Net Price (NETPR)'
      @Semantics.amount.currencyCode: 'DocumentCurrency'
      B.NetPriceAmount,
      @EndUserText.label: 'Order Quantity (MENGE)'
      @Semantics.quantity.unitOfMeasure: 'OrderQuantityUnit'
      B.OrderQuantity,
      @EndUserText.label: 'Total PO Amount (NETWR)'
      @Semantics.amount.currencyCode: 'DocumentCurrency'
      B.NetOrderValue                       as TotalPOAmount,
      @EndUserText.label: 'Contract (KONNR)'
      B.Contract,
      @EndUserText.label: 'Contract Item (KTPNR)'
      B.ContractItem,
      @EndUserText.label: 'Maverick Flag'
      cast( case B.IsOnValidContract when 1 then 'N' else 'Y' end as abap.char(1) ) as MaverickFlag,
      @EndUserText.label: 'Contract Compliance'
      cast( case B.IsOnValidContract when 1 then 'Compliant' else 'Non-Compliant' end
            as abap.char(20) )              as ContractCompliance,
      @EndUserText.label: 'Schedule Line (ETENR)'
      B.ScheduleLine,
      @EndUserText.label: 'Planned Delivery Date (EINDT)'
      B.PlannedDeliveryDate,
      @EndUserText.label: 'GR Date (last receipt)'
      B.LastGoodsReceiptDate,
      @EndUserText.label: 'GR Quantity'
      B.GoodsReceiptQuantity,
      @EndUserText.label: 'GR Amount'
      B.GoodsReceiptAmount,
      @EndUserText.label: 'Delivery Status'
      cast( case when B.GoodsReceiptQuantity <= 0 then 'Pending'
                 when B.IsInFull = 1             then 'Complete'
                 else                                 'Partial' end as abap.char(20) ) as DeliveryStatus,
      @EndUserText.label: 'OTIF Status'
      cast( case when B.IsOTIFEligible = 0                 then 'Not Due'
                 when B.GoodsReceiptQuantity <= 0          then 'Not Delivered'
                 when B.IsOnTime = 1 and B.IsInFull = 1    then 'OTIF'
                 when B.IsOnTime = 1                       then 'Short'
                 when B.IsInFull = 1                       then 'Late'
                 else                                           'Late and Short' end
            as abap.char(20) )              as OTIFStatus,
      @EndUserText.label: 'Invoice Document (RBKP-BELNR)'
      B.SupplierInvoice,
      @EndUserText.label: 'Invoice Fiscal Year (GJAHR)'
      B.InvoiceFiscalYear,
      @EndUserText.label: 'Invoice Posting Date'
      B.InvoicePostingDate,
      @EndUserText.label: 'Invoice Amount'
      B.InvoiceAmount,
      @EndUserText.label: 'AP Status'
      cast( case when B.InvoiceAmount = 0                                   then 'Not Invoiced'
                 when B.APOpenAmount <> 0 and B.APClearedAmount <> 0       then 'Partially Cleared'
                 when B.APOpenAmount <> 0                                   then 'Open'
                 when B.APClearedAmount <> 0                                then 'Cleared'
                 else                                                            'Not Posted to AP' end
            as abap.char(20) )              as APStatus,
      @EndUserText.label: 'AP Amount'
      cast( B.APOpenAmount + B.APClearedAmount as abap.dec(17,2) ) as APAmount,
      @EndUserText.label: 'Payment Baseline Date (ZFBDT)'
      B.PaymentBaselineDate,
      @EndUserText.label: 'AP Payment Terms (ZTERM)'
      B.APPaymentTerms,
      @EndUserText.label: 'Payment Status'
      cast( case when B.InvoiceAmount = 0                                   then 'Not Invoiced'
                 when B.APOpenAmount <> 0 and B.APClearedAmount <> 0       then 'Partially Paid'
                 when B.APOpenAmount <> 0                                   then 'Pending'
                 when B.APClearedAmount <> 0                                then 'Paid'
                 else                                                            'Pending' end
            as abap.char(20) )              as PaymentStatus,
      @EndUserText.label: 'Plant (WERKS)'
      B.Plant,
      @EndUserText.label: 'State (T001W-REGIO)'
      B.Region,

      // ===== Extra attributes =================================================
      B.DocumentCurrency,
      B.OrderQuantityUnit,
      B.NetPriceQuantity,
      B.FiscalYearVariant,
      B.SupplierAccountGroup,
      B.PurchasingGroup,
      B.PurchaseOrderType,
      B.PurchasingProcessingStatus,
      B.CreatedByUser,
      B.CreationDate,
      B.Material,
      B.MaterialGroup,
      B.PurchaseOrderItemText,
      B.PurchasingItemCategory,
      B.AccountAssignmentCategory,
      B.ContractValidityStartDate,
      B.ContractValidityEndDate,
      B.ScheduleLineCount,
      B.FirstGoodsReceiptDate,
      B.InvoiceDocumentCount,
      B.InvoiceQuantity,
      B.APOpenAmount,
      B.APClearedAmount,
      B.ClearingDate,
      B.PlantName,
      B.PlantCountry,
      B.RegionName,
      B.MaterialGroupName,
      B.GLAccount,
      B.AccountAssignmentCostCenter,
      B.DiscountBaseAmount,
      B.CashDiscountTaken,
      B.PaymentBlockReason,
      @EndUserText.label: 'Invoice Qty - GR Qty'
      cast( B.InvoiceQuantity - B.GoodsReceiptQuantity as abap.dec(15,3) ) as InvoiceGRQuantityVariance,
      @EndUserText.label: 'Invoice Discrepancy'
      cast( case when B.BlockedInvoiceLineCount > 0                    then 'Blocked'
                 when B.InvoiceQuantity > B.GoodsReceiptQuantity       then 'Qty Variance'
                 when B.InvoiceUnitPriceNumeric <> B.POUnitPriceNumeric
                  and B.InvoiceUnitPriceNumeric <> 0                   then 'Price Variance'
                 else                                                       'None' end as abap.char(15) ) as InvoiceDiscrepancy,

      // ===== Helper measures so ratio KPIs aggregate correctly ================
      @EndUserText.label: 'PO Item Count'
      1                                      as POItemCount,
      @EndUserText.label: 'Maverick Spend'
      cast( case B.IsOnValidContract when 1 then cast( 0 as abap.dec(17,2) )
                 else B.NetOrderValueNumeric end as abap.dec(17,2) ) as MaverickSpendAmount,
      @EndUserText.label: 'Compliant Spend'
      cast( case B.IsOnValidContract when 1 then B.NetOrderValueNumeric
                 else cast( 0 as abap.dec(17,2) ) end as abap.dec(17,2) ) as CompliantSpendAmount,
      @EndUserText.label: 'OTIF Eligible Items'
      B.IsOTIFEligible                       as OTIFEligibleCount,
      @EndUserText.label: 'OTIF Items'
      case when B.IsOTIFEligible = 1 and B.IsOnTime = 1 and B.IsInFull = 1
           then 1 else 0 end                 as OTIFCount,
      @EndUserText.label: 'Invoiced Qty valued at PO Price'
      cast( B.InvoiceQuantity * B.POUnitPriceNumeric as abap.dec(17,2) ) as InvoicedQtyAtPOPrice,
      @EndUserText.label: 'PO Unit Price (NETWR / MENGE)'
      B.POUnitPriceNumeric                   as POUnitPrice,
      @EndUserText.label: 'Invoice Net Price'
      B.InvoiceUnitPriceNumeric              as InvoiceNetPrice,
      @EndUserText.label: 'Price Variance % (item level, do not SUM)'
      cast( case when B.POUnitPriceNumeric <> 0 and B.InvoiceUnitPriceNumeric <> 0
                 then division( ( B.InvoiceUnitPriceNumeric - B.POUnitPriceNumeric ) * 100,
                                B.POUnitPriceNumeric, 2 )
                 else cast( 0 as abap.dec(9,2) ) end as abap.dec(9,2) ) as PriceVariancePercent
}
