// Vendor line items of FI documents created by MIRO (AWTYP = RMRP).
// Replaces BSIK/BSAK (compatibility views in S/4HANA).
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PSC: Vendor AP Item for Supplier Invoice'
@Metadata.ignorePropagatedAnnotations: true
@VDM.viewType: #BASIC
@ObjectModel.usageType: { serviceQuality: #C, sizeCategory: #XXL, dataClass: #TRANSACTIONAL }
define view entity ZI_PSC_VendorAPItem
  as select from bseg
    inner join   bkpf on  bkpf.bukrs = bseg.bukrs
                      and bkpf.belnr = bseg.belnr
                      and bkpf.gjahr = bseg.gjahr
{
  key bseg.bukrs as CompanyCode,                       // BUKRS
  key bseg.belnr as AccountingDocument,                // BELNR (FI doc)
  key bseg.gjahr as FiscalYear,                        // GJAHR
  key bseg.buzei as AccountingDocumentItem,            // BUZEI
      bseg.lifnr as Supplier,                          // LIFNR
      bseg.zfbdt as PaymentBaselineDate,               // ZFBDT
      bseg.zterm as PaymentTerms,                      // ZTERM
      bseg.augdt as ClearingDate,                      // AUGDT
      bseg.augbl as ClearingAccountingDocument,        // AUGBL ('' = open, filled = cleared)
      bseg.shkzg as DebitCreditCode,                   // SHKZG
      cast( bseg.skfbt as abap.dec(17,2) ) as DiscountBaseAmount,     // SKFBT (doc currency)
      cast( bseg.wskto as abap.dec(17,2) ) as CashDiscountAmount,     // WSKTO (doc currency)
      dats_add_days( bseg.zfbdt, cast( bseg.zbd1t as abap.int4 ), 'INITIAL' ) as CashDiscountDueDate,
      // AWKEY for RMRP = RBKP-BELNR(10) + RBKP-GJAHR(4)
      cast( substring( bkpf.awkey, 1, 10 ) as abap.char(10) )  as SupplierInvoice,
      cast( substring( bkpf.awkey, 11, 4 ) as abap.numc(4) )   as SupplierInvoiceFiscalYear,
      concat( substring( bkpf.awkey, 11, 4 ),
              substring( bkpf.awkey, 1, 10 ) )                  as InvoiceSortKey
}
where bkpf.awtyp = 'RMRP'
  and bseg.koart = 'K'
