@AbapCatalog.viewEnhancementCategory: [#NONE]
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Purchase Register - Composite View'
@Metadata.ignorePropagatedAnnotations: true
define view entity ZI_PurchaseRegister_08
  as select from ZI_PurReg_InvoiceBase as _Invoice
  /* FI Document Header  */
  inner join bkpf as _AcctDoc
    on  _AcctDoc.awkey = _Invoice.AwKey
    and _AcctDoc.blart = 'RE'

  /*  Vendor Master  */
  left outer join ZI_PurReg_VendorInfo as _Vendor
    on  _Vendor.Vendor = _Invoice.Vendor

  /*  Material Info (description + HSN + type)  */
  left outer join ZI_PurReg_MaterialInfo_03 as _Material
    on  _Material.Material = _Invoice.Material
    and _Material.Plant    = _Invoice.Plant

  /*  CGST Tax Rate  */
  left outer join ZI_PurReg_TaxCondition_04 as _CGST
    on  _CGST.TaxCode       = _Invoice.TaxCode
    and _CGST.ConditionType  = 'CGST'

  /*  SGST Tax Rate  */
  left outer join ZI_PurReg_TaxCondition_04 as _SGST
    on  _SGST.TaxCode       = _Invoice.TaxCode
    and _SGST.ConditionType  = 'SGST'

  /*  IGST Tax Rate  */
  left outer join ZI_PurReg_TaxCondition_04 as _IGST
    on  _IGST.TaxCode       = _Invoice.TaxCode
    and _IGST.ConditionType  = 'IGST'

  /* ── ACDOCA Amounts (aggregated by doc + PO line) ────────────────── */
  left outer join ZI_PurReg_AcdocaAmounts_05 as _Amounts
    on  _Amounts.CompanyCode       = _AcctDoc.bukrs
    and _Amounts.DocumentNumber    = _AcctDoc.belnr
    and _Amounts.FiscalYear        = _AcctDoc.gjahr
    and _Amounts.PurchaseOrder     = _Invoice.PurchaseOrder
    and _Amounts.PurchaseOrderItem = _Invoice.PurchaseOrderItem
    and _Amounts.ReferenceItem     = _Invoice.InvoiceLineItem

  /*  BSEG Aggregated (VAT, gross, TDS, vendor GL)  */
  left outer join ZI_PurReg_BsegAggregated_06 as _BsegAggr
    on  _BsegAggr.CompanyCode    = _AcctDoc.bukrs
    and _BsegAggr.DocumentNumber = _AcctDoc.belnr
    and _BsegAggr.FiscalYear     = _AcctDoc.gjahr

  /*  GRN / MIGO Details  */
  left outer join ZI_PurReg_GRNInfo_07 as _GRN
    on  _GRN.PurchaseOrder     = _Invoice.PurchaseOrder
    and _GRN.PurchaseOrderItem = _Invoice.PurchaseOrderItem

  /*  GRN Document Date (from MKPF via rseg-lfbnr)  */
  left outer join mkpf as _GrnDoc
    on  _GrnDoc.mblnr = _Invoice.ReferenceDocNumber
    and _GrnDoc.mjahr  = _Invoice.FiscalYear

  /*  Valuation Class Description  */
  left outer join t025t as _ValClassText
    on  _ValClassText.bklas = _Invoice.ValuationClass
    and _ValClassText.spras = $session.system_language

  /*  GL from Valuation Class  */
  left outer join t030 as _ValClassGL
    on  _ValClassGL.bklas = _Invoice.ValuationClass
    and _ValClassGL.ktopl = '1111'
    and _ValClassGL.ktosl = 'BSX'
    and _ValClassGL.bwmod = ''

  /*  PO Header  */
  left outer join ekko as _PO
    on  _PO.ebeln = _Invoice.PurchaseOrder

  /*  PO Item (for material desc fallback & place of supply)  */
  left outer join ekpo as _POItem
    on  _POItem.ebeln = _Invoice.PurchaseOrder
    and _POItem.ebelp = _Invoice.PurchaseOrderItem

  /*  Place of Supply: address → region text  */
  left outer join adrc as _PoAddress
    on  _PoAddress.addrnumber = _POItem.adrnr

  left outer join t005u as _PosRegion
    on  _PosRegion.bland = _PoAddress.region
    and _PosRegion.spras = $session.system_language

  /*  Plant master (fallback for place of supply)  */
  left outer join t001w as _PlantMaster
    on  _PlantMaster.werks = _Invoice.Plant

  left outer join t005u as _PlantRegion
    on  _PlantRegion.land1 = _PlantMaster.land1
    and _PlantRegion.bland = _PlantMaster.regio
    and _PlantRegion.spras = $session.system_language

  /*  Tax Code Description (5 kalsm variants)  */
  left outer join t007s as _TxTAXD
    on  _TxTAXD.mwskz = _Invoice.TaxCode
    and _TxTAXD.kalsm = 'TAXD'
    and _TxTAXD.spras = $session.system_language

  left outer join t007s as _TxZTAXEG
    on  _TxZTAXEG.mwskz = _Invoice.TaxCode
    and _TxZTAXEG.kalsm = 'ZTAXEG'
    and _TxZTAXEG.spras = $session.system_language

  left outer join t007s as _TxTAXUS
    on  _TxTAXUS.mwskz = _Invoice.TaxCode
    and _TxTAXUS.kalsm = 'TAXUS'
    and _TxTAXUS.spras = $session.system_language

  left outer join t007s as _TxTAXNL
    on  _TxTAXNL.mwskz = _Invoice.TaxCode
    and _TxTAXNL.kalsm = 'TAXNL'
    and _TxTAXNL.spras = $session.system_language

  left outer join t007s as _TxTAXTR
    on  _TxTAXTR.mwskz = _Invoice.TaxCode
    and _TxTAXTR.kalsm = 'TAXTR'
    and _TxTAXTR.spras = $session.system_language

  /*  BSET — VAT Rate  */
  left outer join bset as _Bset
    on  _Bset.bukrs = _AcctDoc.bukrs
    and _Bset.belnr = _AcctDoc.belnr
    and _Bset.gjahr = _AcctDoc.gjahr

  /*  Service line items (for service PO description)  */
  left outer join esll as _ServiceLine
    on  _ServiceLine.packno = _Invoice.PackageNumber
    and _ServiceLine.introw = _Invoice.InternalRow

{
  /*  KEY FIELDS                                                   */
  key _AcctDoc.belnr                                            as DocumentNo,
  key _AcctDoc.gjahr                                            as FiscalYear,
  key _Invoice.InvoiceLineItem                                  as InvoiceLineItem,


  /*  DOCUMENT HEADER                                              */
      _Invoice.CompanyCode                                      as CompanyCode,
      _Invoice.Plant                                            as Plant,
      _Invoice.InvoiceDocNumber                                 as MiroInvoiceNo,
      _Invoice.DocumentType                                     as DocumentType,
//      _Invoice.Currency                                         as Currency,
      _Invoice.ExchangeRate                                     as ExchangeRate,

      /* Posting Date (formatted as YYYY-MM-DD in ABAP) */
      _Invoice.PostingDate                                      as PostingDate,
      _Invoice.DocumentDate                                     as DocumentDate,

  
  /*  VENDOR DATA                                                  */
      _Invoice.Vendor                                           as Vendor,
      _Vendor.VendorName                                        as VendorName,
      _Vendor.City                                              as City,
      _Vendor.StateName                                         as State,
      _Vendor.CountryName                                       as Country,
      _Vendor.TaxNumber1                                        as TaxNumber1,
      _Vendor.GSTNumber                                         as GSTNumber,
      _Vendor.PANNumber                                         as PANNumber,
      _Vendor.VATNumber                                         as VATNumber,
      _Vendor.InvoiceType                                       as InvoiceType,

  
  /*  VENDOR INVOICE / REFERENCE                                   */
      _Invoice.VendorInvoiceNo                                  as VendorInvoiceNo,
      _AcctDoc.xblnr_alt                                        as ODNNumber,


  /*  PO DATA                                                      */
      _Invoice.PurchaseOrder                                    as PurchaseOrder,
      _Invoice.PurchaseOrderItem                                as PurchaseOrderItem,
      _PO.bedat                                                 as PODate,


  /*  MATERIAL DATA                                                */
      _Invoice.Material                                         as Material,
      case when _Material.MaterialDescription <> ''
           then _Material.MaterialDescription
           when _Invoice.ItemCategory = '9' and _ServiceLine.ktext1 <> ''
           then _ServiceLine.ktext1
           else _POItem.txz01
      end                                                       as MaterialDescription,

      /* HSN code with fallback to item text                       */
      case when _Material.HSNCode <> ''
           then _Material.HSNCode
           else _Invoice.ItemText
      end                                                       as HSNCode,

      _Material.MaterialType                                    as MaterialType,

  /*  QUANTITY / UOM                                               */
//      _Invoice.Quantity                                         as Quantity,
//      case when _Invoice.BaseUnitOfMeasure <> ''
//           then _Invoice.BaseUnitOfMeasure
//           else _Invoice.OrderUnit
//      end                                                       as UOM,
//      _Invoice.UnitRate                                         as UnitRate,


  /*  TAX CODE                                                     */
      _Invoice.TaxCode                                          as TaxCode,

      /* Tax code description (selected by company code → kalsm)   */
      case _Invoice.CompanyCode
        when '5001' then _TxZTAXEG.text1
        when '5002' then _TxTAXD.text1
        when '5011' then _TxTAXD.text1
        when '5003' then _TxTAXUS.text1
        when '5004' then _TxTAXNL.text1
        when '5012' then _TxTAXTR.text1
        else cast( '' as abap.char( 50 ) )
      end                                                       as TaxCodeDescription,

  /*  GL ACCOUNTS                                                  */
      case when _ValClassGL.konts <> ''
           then _ValClassGL.konts
           when _Amounts.FreightGLAccount <> ''
           then _Amounts.FreightGLAccount
           else cast( '' as abap.char( 10 ) )
      end                                                       as GLCode,

      _BsegAggr.VendorReconGL                                  as VendorReconGL,

  /*  AMOUNTS                                                      */
      _Amounts.MainAmtDocCurr                                   as AmountInDocCurr,
      _Amounts.OtherAmtDocCurr                                  as OtherChargesDocCurr,
      _Amounts.MainAmtLocalCurr                                 as AmountInLocalCurr,
      _Amounts.OtherAmtLocalCurr                                as OtherChargesLocalCurr,
      _Amounts.HardCurrencyAmt                                  as HardCurrencyAmount,
      _Amounts.HARDCURRENCYKEY                                  as HardCurrencyKey,

//      /* Taxable Amount = main + other (local currency)            */
//      cast( _Amounts.MainAmtLocalCurr as abap.curr( 15, 2 ) )
//        + cast( _Amounts.OtherAmtLocalCurr as abap.curr( 15, 2 ) )
//                                                                as TaxableAmount,


  /*  GST TAX RATES & AMOUNTS                                     */
      _CGST.TaxRate                                             as CGSTRate,
      _SGST.TaxRate                                             as SGSTRate,
      _IGST.TaxRate                                             as IGSTRate,

      /* Total GST Rate */
      cast( coalesce( _CGST.TaxRate, cast( 0 as abap.dec( 5, 2 ) ) ) as abap.dec( 5, 2 ) )
        + cast( coalesce( _SGST.TaxRate, cast( 0 as abap.dec( 5, 2 ) ) ) as abap.dec( 5, 2 ) )
        + cast( coalesce( _IGST.TaxRate, cast( 0 as abap.dec( 5, 2 ) ) ) as abap.dec( 5, 2 ) )
                                                                as TotalGSTRate,

      /* CGST Amount = TaxableAmount × CGSTRate / 100 */
//      ( cast( _Amounts.MainAmtLocalCurr as abap.curr( 15, 2 ) )
//        + cast( _Amounts.OtherAmtLocalCurr as abap.curr( 15, 2 ) ) )
//        * coalesce( _CGST.TaxRate, cast( 0 as abap.dec( 5, 2 ) ) )
//        / cast( 100 as abap.dec( 5, 2 ) )
//                                                                as CGSTAmount,

      /* SGST Amount */
//      ( cast( _Amounts.MainAmtLocalCurr as abap.curr( 15, 2 ) )
//        + cast( _Amounts.OtherAmtLocalCurr as abap.curr( 15, 2 ) ) )
//        * coalesce( _SGST.TaxRate, cast( 0 as abap.dec( 5, 2 ) ) )
//        / cast( 100 as abap.dec( 5, 2 ) )
//                                                                as SGSTAmount,

      /* IGST Amount */
//      ( cast( _Amounts.MainAmtLocalCurr as abap.curr( 15, 2 ) )
//        + cast( _Amounts.OtherAmtLocalCurr as abap.curr( 15, 2 ) ) )
//        * coalesce( _IGST.TaxRate, cast( 0 as abap.dec( 5, 2 ) ) )
//        / cast( 100 as abap.dec( 5, 2 ) )
//                                                                as IGSTAmount,

