      /* GRN Date — from mkpf (primary) or ekbe (fallback)         */
      case when _GrnDoc.budat is not initial
           then _GrnDoc.budat
           else _GRN.GrnDate
      end                                                       as GRNDate,

      _GRN.GrnNumber                                            as MIGONumber,
      _GRN.GrnDate                                              as MIGODate,

  /*  VALUATION CLASS                                              */
      _Invoice.ValuationClass                                   as ValuationClass,
      _ValClassText.bkbez                                       as ValuationClassDesc,


  /*  PLACE OF SUPPLY                                              */
      /* Place of supply: PO address region → plant region fallback */
      case when _PoAddress.region <> ''
           then concat( _PoAddress.region,
                  concat( cast( '-' as abap.char( 1 ) ),
                          coalesce( _PosRegion.bezei, cast( '' as abap.char( 20 ) ) ) ) )
           when _PlantMaster.regio <> ''
           then concat( _PlantMaster.regio,
