             or _Invoice.TaxCode = 'DC' or _Invoice.TaxCode = 'DD'
             or _Invoice.TaxCode = 'DE' or _Invoice.TaxCode = 'DF'
             or _Invoice.TaxCode = 'DG' or _Invoice.TaxCode = 'DH'
             or _Invoice.TaxCode = 'DI' or _Invoice.TaxCode = 'DJ'
             or _Invoice.TaxCode = 'DK' or _Invoice.TaxCode = 'DL'
             or _Invoice.TaxCode = 'GS' or _Invoice.TaxCode = 'GT'
             or _Invoice.TaxCode = 'GU' or _Invoice.TaxCode = 'GV'
             or _Invoice.TaxCode = 'GW' or _Invoice.TaxCode = 'GX'
             or _Invoice.TaxCode = 'GY' or _Invoice.TaxCode = 'GZ'
             or _Invoice.TaxCode = 'P5' or _Invoice.TaxCode = 'P6'
             or _Invoice.TaxCode = 'P7' or _Invoice.TaxCode = 'P8'
             or _Invoice.TaxCode = 'HA' or _Invoice.TaxCode = 'HB'
             or _Invoice.TaxCode = 'HC' or _Invoice.TaxCode = 'HD'
             or _Invoice.TaxCode = 'HE' or _Invoice.TaxCode = 'HF'
             or _Invoice.TaxCode = 'HG' or _Invoice.TaxCode = 'HH'
             or _Invoice.TaxCode = 'JS' or _Invoice.TaxCode = 'JT'
             or _Invoice.TaxCode = 'JU' or _Invoice.TaxCode = 'JV'
