define view entity ZI_PurchRegGstRate_09 as select from a003
        inner join konp on konp.knumh = a003.knumh
                    and konp.loevm_ko = ''
{
    key a003.mwskz                                                          as Mwskz,

      max( case when a003.kschl = 'CGST' then cast( konp.kbetr as abap.dec( 15, 3 ) ) / 10 end )      as CgstRate,
      max( case when a003.kschl = 'SGST' then cast( konp.kbetr as abap.dec( 15, 3 ) ) / 10 end )      as SgstRate,
      max( case when a003.kschl = 'IGST' then cast( konp.kbetr as abap.dec( 15, 3 ) ) / 10 end )      as IgstRate,
      max( case when ( a003.kschl = 'JICR' or a003.kschl = 'JISR' or a003.kschl = 'JIUR'
                     or a003.kschl = 'JIIR' or a003.kschl = 'JCIR' )
                     and a003.knumh <> ''
                then 'X' end )                                            as HasReverseCharge
}
where a003.kappl = 'TX'
  and a003.aland = 'IN'
group by a003.mwskz
