  key belnr                                                 as DocumentNumber,
  key gjahr                                                 as FiscalYear,
  key ebeln                                                 as PurchaseOrder,
  key ebelp                                                 as PurchaseOrderItem,
  key awitem                                                as ReferenceItem,

  sum(case when ktosl = 'WRX'or ktosl = 'BSX'or ktosl = 'KBS'or ktosl = 'FR1'or ktosl = 'ANL'
        then cast( wsl as abap.dec(23,2) )
