or ktosl = 'FR1'
or ktosl = 'ANL'
then cast( hsl as abap.dec( 23, 2 ) )
else cast( 0 as abap.dec( 23, 2 ) )
end) as MainAmtLocalCurr,


sum(case when ktosl <> 'WRX'and ktosl <> 'BSX'and ktosl <> 'KBS'and ktosl <> 'FR1'and ktosl <> 'ANL'
         then cast( wsl as abap.dec( 23, 2 ) )
             else cast( 0 as abap.dec( 23, 2 ) )end) as OtherAmtDocCurr,

