         then cast( hsl as abap.dec( 23, 2 ) )
             else cast( 0 as abap.dec( 23, 2 ) )end) as OtherAmtLocalCurr,

sum(cast( osl as abap.dec( 23, 2 ) )) as HardCurrencyAmt, 


max(case when ktosl = 'FR1'then racct else cast( '' as abap.char( 10 ) )end) as FreightGLAccount,
