  key bukrs                                                    as CompanyCode,
  key belnr                                                    as DocumentNumber,
  key gjahr                                                    as FiscalYear,

    //  Gross Total 
//      sum( case when buzid = '' and shkzg = 'H'
//                then dmbtr
//                else cast( 0 as abap.curr( 15, 2 ) )
//           end )                                                   as GrossTotal,

sum(
  case
    when buzid = '' and shkzg = 'H'
    then cast( dmbtr as abap.dec( 15, 2 ) )
    else cast( 0 as abap.dec( 15, 2 ) )
  end
