sum(
  case
    when buzid = 'T'
    then cast( dmbtr as abap.dec( 15, 2 ) )
    else cast( 0 as abap.dec( 15, 2 ) )
  end
) as VatAmount,

  /* VAT Code  */
  max( case when buzid = 'T'
            then ktosl
            else cast( '' as abap.char( 3 ) )
       end )                                                   as VatCode,



  /* Tax Base Amount in Doc Currency */
