//max( fwbas ) as TaxBaseAmount,

  /* Vendor Reconciliation GL */
  max( case when koart = 'K' and lifnr <> ''
            then hkont
            else cast( '' as abap.char( 10 ) )
       end )                                                   as VendorReconGL,

  /* TDS Amount posting key 50 */
