//             and buzid = '' and mwskz = ''
//            then dmbtr
//            else cast( 0 as abap.curr( 15, 2 ) )
//       end )                                                   as TdsAmountDebit,

  /* Business Area  */
  max( case when gsber <> ''
            then gsber
            else cast( '' as abap.char( 4 ) )
       end )                                                   as BusinessArea
}
group by bukrs, belnr, gjahr
