define view entity ZMDGCNWFTSKLST01
  as select from    swwwihead       as WFTasks
    left outer join ZMDGCNUSERDET01 as DialogUser01 on DialogUser01.USER_ID = WFTasks.wi_cruser
    left outer join ZMDGCNUSERDET01 as DialogUser02 on DialogUser02.USER_ID = WFTasks.wi_aagent
  association [1]    to ZMDGCNWFHEADER01 as _wfheader    on $projection.ABAP_Workflow_ID = _wfheader.ABAP_Workflow_ID
  association [1..*] to ZMDGCNWFPSBAGT01 as _wftaskagnts on $projection.Workflow_Task_ID = _wftaskagnts.Workflow_Task_ID
{
      @EndUserText.label: 'Workflow Task Number'
      @UI.lineItem: [{ position: 10 }]
  key WFTasks.wi_id          as Workflow_Task_ID,
      @EndUserText.label: 'Workflow Task Text'
      @UI.lineItem: [{ position: 20 }]
      WFTasks.wi_text        as Workflow_Task_Text,
      @EndUserText.label: 'Workflow Task Type'
      @UI.lineItem: [{ position: 30 }]
      @UI.identification: [{ position: 30, importance: #HIGH }]
      @ObjectModel.text.element: ['Workflow_Task_Type_Text']
      WFTasks.wi_type        as Workflow_Task_Type,
      @Semantics.text: true
      @UI.hidden: true
      case WFTasks.wi_type
        when 'A' then 'Work Queue Task'
        when 'B' then 'Background Task'
        when 'C' then 'Container Linkage Task'
        when 'D' then 'Deadline Task'
        when 'E' then 'Wait Event Task'
        when 'N' then 'Notification Task'
        when 'P' then 'Remote Task'
        when 'Q' then 'Dialog Block Task'
        when 'R' then 'Remote HTTP Task'
        when 'W' then 'Dialog Task'
        when 'X' then 'Block Task'
        else 'Unknown'
        end                  as Workflow_Task_Type_Text,
      @EndUserText.label: 'Workflow Task Created On'
      @UI.lineItem: [{ position: 40 }]
      @UI.identification: [{ position: 10, importance: #HIGH }]
      WFTasks.wi_cd          as Workflow_Task_Created_On,
      @EndUserText.label: 'Workflow Task Created At'
      @UI.lineItem: [{ position: 50 }]
      @UI.identification: [{ position: 20, importance: #HIGH }]
      WFTasks.wi_ct          as Workflow_Task_Created_At,
      @EndUserText.label: 'Workflow Task Initiator Name'
      @UI.lineItem: [{ position: 60 }]
      @UI.identification: [{ position: 40, importance: #HIGH }]
      @ObjectModel.text.element: ['Workflow_Task_Initiator_Name']
      WFTasks.wi_cruser      as Workflow_Task_Initiator_ID,
      @EndUserText.label: 'Workflow Task Initiator By Name'
      @Semantics.text: true
      @UI.hidden: true
      DialogUser01.FULL_NAME as Workflow_Task_Initiator_Name,
      @EndUserText.label: 'Workflow Task Initiator Email ID'
      @UI.lineItem: [{ position: 70 }]
      @UI.identification: [{ position: 50, importance: #HIGH }]
      DialogUser01.EMAIL_ID  as Workflow_Task_Initiator_Email,
      @EndUserText.label: 'Workflow Task Actual Agent Name'
      @UI.lineItem: [{ position: 80 }]
      @UI.identification: [{ position: 60, importance: #HIGH }]
      @ObjectModel.text.element: ['Workflow_Task_Actual_Agnt_Name']
      WFTasks.wi_aagent      as Workflow_Task_Actual_Agnt_ID,
      @EndUserText.label: 'Workflow Task Agent By Name'
      @UI.hidden: true
      @Semantics.text: true
      DialogUser02.FULL_NAME as Workflow_Task_Actual_Agnt_Name,
      @EndUserText.label: 'Workflow Task Actual Agent Email ID'
      @UI.lineItem: [{ position: 90 }]
      @UI.identification: [{ position: 70, importance: #HIGH }]
      DialogUser02.EMAIL_ID  as Workflow_Tsk_Actual_Agnt_Email,
      @EndUserText.label: 'Workflow Task Status'
      @UI.lineItem: [{ position: 100 }]
      @UI.identification: [{ position: 80, importance: #HIGH }]
      case WFTasks.wi_stat
            when 'WAITING' then 'Waiting'
            when 'READY' then 'Ready'
            when 'SELECTED' then 'Accepted'
            when 'STARTED' then 'In Process'
            when 'ERROR' then 'Error'
            when 'COMMITTED' then 'Executed'
            when 'COMPLETED' then 'Completed'
            when 'CANCELLED' then 'Logically Deleted'
            when 'CHECKED' then 'In Preparation'
            when 'EXCPCAUGHT' then 'Exception Caught'
            when 'EXCPHANDLR' then 'Exception Active'
            else 'Unknown'
          end                as Workflow_Task_Status,
      @UI.hidden: true
      WFTasks.wi_rh_task     as Workflow_Task_Number,
      @EndUserText.label: 'Workflow Task Priority'
      @UI.lineItem: [{ position: 110 }]
      @UI.identification: [{ position: 90, importance: #HIGH }]
      case WFTasks.wi_prio
            when '1' then 'Highest - Express'
            when '2' then 'Very high'
            when '3' then 'Higher'
            when '4' then 'High'
            when '5' then 'Medium'
            when '6' then 'Low'
            when '7' then 'Lower'
            when '8' then 'Very Low'
            when '9' then 'Lowest'
            else 'Unknown Priority'
            end              as Workflow_Task_Priority,
      @UI.hidden: true
      WFTasks.top_wi_id      as ABAP_Workflow_ID,

      // All association items
      @ObjectModel.association.type:[#TO_COMPOSITION_ROOT, #TO_COMPOSITION_PARENT]
      _wfheader,
      @ObjectModel.association.type:[#TO_COMPOSITION_CHILD]
      _wftaskagnts
}
where
  WFTasks.wi_type != 'F'
