@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'SALES ORDER CDS'
@Metadata.ignorePropagatedAnnotations: true
define view ZMY_SALES_OVERVIEW1 as select from vbak as salesorder
{
    salesorder.vbeln as ordernumber,
    salesorder.erdat as createdon,
    salesorder.aedat as change_date,
    salesorder.ernam as name,
    
    case salesorder.auart 
    when 'OR' then 'Standrd order'
    when 'RE' then 'returns'
    else 'other'
    end as ordertypetext,
  
  // For currency conversion 
    cast(salesorder.netwr as abap.dec(13,2)) as netvalue,
    
  //  for multiply 
    salesorder.netwr * 2 as netweight,
    
  //for concatenate 
    concat( salesorder.vbeln, salesorder.erdat ) as concat_field,
 
    
  // for upper case
    upper( salesorder.ernam ) as upper_case,
    
  // days between two dates
  dats_days_between( salesorder.erdat, salesorder.aedat ) as days_betwn,
  
  // Add days to date
  dats_add_days( salesorder.erdat, 30, 'NULL' ) as add_days
    
    
}

where salesorder.auart <> 'RK'
